/** Peachify embed origin — validate postMessage sources against this. */
export const PEACHIFY_ORIGIN = 'https://peachify.top' as const;

export type PeachifyMediaType = 'movie' | 'tv';

export type MediaId = number | string;

/** Keys that accept hide/false/0/off to hide a control. */
export type PeachifyHideControlKey =
  | 'pip'
  | 'cast'
  | 'fullscreen'
  | 'volume'
  | 'servers'
  | 'captions'
  | 'quality'
  | 'play'
  | 'rewind'
  | 'forward'
  | 'timegroup'
  | 'timeslider'
  | 'settings';

export type HideControlValue = boolean | 'false' | '0' | 'off';

export interface PeachifyHideControls {
  pip?: HideControlValue;
  cast?: HideControlValue;
  fullscreen?: HideControlValue;
  volume?: HideControlValue;
  servers?: HideControlValue;
  captions?: HideControlValue;
  quality?: HideControlValue;
  play?: HideControlValue;
  rewind?: HideControlValue;
  forward?: HideControlValue;
  timegroup?: HideControlValue;
  timeslider?: HideControlValue;
  settings?: HideControlValue;
}

export interface PeachifyEmbedOptions extends PeachifyHideControls {
  /** Target audio language (alias: audio). */
  dub?: string;
  audio?: string;
  /** Target subtitle language or label (alias: subtitle). */
  sub?: string;
  subtitle?: string;
  /** Preferred quality, e.g. 1080 or 1080p (alias: q). */
  quality?: string | number;
  q?: string | number;
  /** Force a specific provider first. */
  server?: string;
  /** Override provider API base URL. */
  api?: string;
  /** Start playback at this time in seconds (aliases: progress, t). */
  startAt?: number;
  progress?: number;
  t?: number;
  /** TV only: auto-advance to next episode (boolean or seconds threshold). */
  autoNext?: boolean | number;
  /** TV only: show manual Next Episode button. */
  showNextBtn?: boolean;
  showAutoNextButton?: boolean;
  nextEpisodeButton?: boolean;
  /** UI accent color hex without #, e.g. B54666 */
  accent?: string;
  /** Default true; pass false to disable autoplay. */
  autoPlay?: boolean;
}

export interface PeachifyMovieTarget {
  type: 'movie';
  mediaId: MediaId;
  options?: PeachifyEmbedOptions;
}

export interface PeachifyTvTarget {
  type: 'tv';
  mediaId: MediaId;
  season: number;
  episode: number;
  options?: PeachifyEmbedOptions;
}

export type PeachifyEmbedTarget = PeachifyMovieTarget | PeachifyTvTarget;

/** Outbound postMessage commands. */
export type PeachifyCommand =
  | 'play'
  | 'pause'
  | 'seek'
  | 'start'
  | 'setVolume'
  | 'toggleMute'
  | 'toggleFullscreen'
  | 'getStatus';

export interface PeachifyOutboundMessage {
  command: PeachifyCommand;
  value?: number;
}

export type PeachifyPlayerEventName =
  | 'play'
  | 'pause'
  | 'seeked'
  | 'ended'
  | 'timeupdate'
  | string;

export interface PeachifyPlayerEventData {
  event: PeachifyPlayerEventName;
  currentTime: number;
  duration: number;
  tmdbId?: number;
  mediaType?: PeachifyMediaType;
  season?: number;
  episode?: number;
}

export interface PeachifyPlayerEventMessage {
  type: 'PLAYER_EVENT';
  data: PeachifyPlayerEventData;
}

export interface PeachifyMediaDataMessage {
  type: 'MEDIA_DATA';
  data: PeachifyProgressStore;
}

export type PeachifyInboundMessage =
  | PeachifyPlayerEventMessage
  | PeachifyMediaDataMessage;

export interface PeachifyWatchProgress {
  watched: number;
  duration: number;
}

export interface PeachifyEpisodeProgress {
  season: string;
  episode: string;
  progress: PeachifyWatchProgress;
}

export interface PeachifyMediaProgressEntry {
  id: number;
  type: PeachifyMediaType;
  title: string;
  poster_path?: string;
  backdrop_path?: string;
  progress: PeachifyWatchProgress;
  last_season_watched?: string;
  last_episode_watched?: string;
  show_progress?: Record<string, PeachifyEpisodeProgress>;
  last_updated?: number;
}

/** Full continue-watching store keyed by media id string. */
export type PeachifyProgressStore = Record<string, PeachifyMediaProgressEntry>;

export interface PeachifyControllerOptions {
  /** Allowed postMessage origin. Default: https://peachify.top */
  origin?: string;
  /** Persist MEDIA_DATA payloads. Default: true */
  persistProgress?: boolean;
  /** localStorage key for progress. Default: peachifyProgress */
  storageKey?: string;
  /** Throttle timeupdate callbacks (ms). Default: 1000 */
  timeupdateThrottleMs?: number;
  /** Called when MEDIA_DATA arrives (after optional persist). */
  onMediaData?: (store: PeachifyProgressStore) => void;
  /** Called on every PLAYER_EVENT (timeupdate throttled). */
  onPlayerEvent?: (data: PeachifyPlayerEventData) => void;
}

import {
  PEACHIFY_ORIGIN,
  type HideControlValue,
  type MediaId,
  type PeachifyEmbedOptions,
  type PeachifyEmbedTarget,
  type PeachifyHideControlKey,
} from './types';

const HIDE_CONTROL_KEYS: PeachifyHideControlKey[] = [
  'pip',
  'cast',
  'fullscreen',
  'volume',
  'servers',
  'captions',
  'quality',
  'play',
  'rewind',
  'forward',
  'timegroup',
  'timeslider',
  'settings',
];

function encodeMediaId(mediaId: MediaId): string {
  const raw = String(mediaId).trim();
  if (/^tt\d+$/i.test(raw)) {
    return raw.toLowerCase();
  }
  const numeric = Number(raw);
  if (!Number.isFinite(numeric) || numeric <= 0) {
    throw new Error(
      `Invalid mediaId "${mediaId}". Use a TMDB numeric id or an IMDb id starting with "tt".`,
    );
  }
  return String(Math.trunc(numeric));
}

function appendHideParams(
  params: URLSearchParams,
  options: PeachifyEmbedOptions,
): void {
  for (const key of HIDE_CONTROL_KEYS) {
    const value = options[key];
    if (value === undefined) continue;
    params.set(key, hideValueToQuery(value));
  }
}

function hideValueToQuery(value: HideControlValue): string {
  if (value === true) return 'hide';
  if (value === false) return 'false';
  return String(value);
}

function setIfDefined(
  params: URLSearchParams,
  key: string,
  value: string | number | boolean | undefined,
): void {
  if (value === undefined) return;
  if (typeof value === 'boolean') {
    params.set(key, value ? 'true' : 'false');
    return;
  }
  params.set(key, String(value));
}

/**
 * Build a Peachify embed URL with path and query parameters.
 */
export function buildPeachifyEmbedUrl(
  target: PeachifyEmbedTarget,
  baseOrigin: string = PEACHIFY_ORIGIN,
): string {
  const mediaId = encodeMediaId(target.mediaId);
  const options = target.options ?? {};

  let path: string;
  if (target.type === 'movie') {
    path = `/embed/movie/${mediaId}`;
  } else {
    const season = Math.max(1, Math.trunc(target.season));
    const episode = Math.max(1, Math.trunc(target.episode));
    path = `/embed/tv/${mediaId}/${season}/${episode}`;
  }

  const url = new URL(path, baseOrigin);
  const params = url.searchParams;

  const dub = options.dub ?? options.audio;
  const sub = options.sub ?? options.subtitle;
  const quality = options.quality ?? options.q;
  const startAt = options.startAt ?? options.progress ?? options.t;

  setIfDefined(params, 'dub', dub);
  setIfDefined(params, 'sub', sub);
  setIfDefined(params, 'quality', quality);
  setIfDefined(params, 'server', options.server);
  setIfDefined(params, 'api', options.api);
  setIfDefined(params, 'startAt', startAt);

  if (target.type === 'tv') {
    if (options.autoNext !== undefined) {
      setIfDefined(params, 'autoNext', options.autoNext);
    }
    const showNext =
      options.showNextBtn ??
      options.showAutoNextButton ??
      options.nextEpisodeButton;
    if (showNext !== undefined) {
      setIfDefined(params, 'showNextBtn', showNext);
    }
  }

  if (options.accent) {
    params.set('accent', options.accent.replace(/^#/, ''));
  }

  if (options.autoPlay === false) {
    params.set('autoPlay', 'false');
  }

  appendHideParams(params, options);

  return url.toString();
}

/**
 * Read resume position (seconds) for a movie or TV episode from a progress store.
 */
export function getResumeSeconds(
  store: Record<string, { progress?: { watched?: number; duration?: number }; show_progress?: Record<string, { progress?: { watched?: number; duration?: number } }> }> | null | undefined,
  mediaId: MediaId,
  season?: number,
  episode?: number,
  /** Skip resume if within this many seconds of the end. Default: 30 */
  endThresholdSeconds = 30,
): number | undefined {
  if (!store) return undefined;

  const entry = store[String(mediaId)];
  if (!entry) return undefined;

  let watched: number | undefined;
  let duration: number | undefined;

  if (season != null && episode != null && entry.show_progress) {
    const key = `s${season}e${episode}`;
    const ep = entry.show_progress[key];
    watched = ep?.progress?.watched;
    duration = ep?.progress?.duration;
  } else {
    watched = entry.progress?.watched;
    duration = entry.progress?.duration;
  }

  if (watched == null || !Number.isFinite(watched) || watched <= 0) {
    return undefined;
  }

  if (
    duration != null &&
    Number.isFinite(duration) &&
    duration - watched <= endThresholdSeconds
  ) {
    return undefined;
  }

  return Math.floor(watched);
}

import type { PeachifyProgressStore } from './types';

const DEFAULT_STORAGE_KEY = 'peachifyProgress';

export function loadPeachifyProgress(
  storageKey = DEFAULT_STORAGE_KEY,
  storage: Storage = localStorage,
): PeachifyProgressStore {
  try {
    const raw = storage.getItem(storageKey);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as PeachifyProgressStore;
    }
  } catch {
    // Corrupt storage — start fresh
  }
  return {};
}

export function savePeachifyProgress(
  store: PeachifyProgressStore,
  storageKey = DEFAULT_STORAGE_KEY,
  storage: Storage = localStorage,
): void {
  storage.setItem(storageKey, JSON.stringify(store));
}

export function mergePeachifyProgress(
  incoming: PeachifyProgressStore,
  storageKey = DEFAULT_STORAGE_KEY,
  storage: Storage = localStorage,
): PeachifyProgressStore {
  const existing = loadPeachifyProgress(storageKey, storage);
  const merged: PeachifyProgressStore = { ...existing, ...incoming };
  savePeachifyProgress(merged, storageKey, storage);
  return merged;
}

export function getMediaProgress(
  store: PeachifyProgressStore,
  mediaId: string | number,
): PeachifyProgressStore[string] | undefined {
  return store[String(mediaId)];
}

export function getCompletionRatio(entry: {
  progress?: { watched?: number; duration?: number };
}): number {
  const { watched = 0, duration = 0 } = entry.progress ?? {};
  if (!duration || duration <= 0) return 0;
  return Math.min(1, Math.max(0, watched / duration));
}

import { mergePeachifyProgress } from './progressStorage';
import {
  PEACHIFY_ORIGIN,
  type PeachifyCommand,
  type PeachifyControllerOptions,
  type PeachifyInboundMessage,
  type PeachifyOutboundMessage,
  type PeachifyPlayerEventData,
  type PeachifyProgressStore,
} from './types';

function isPeachifyInboundMessage(data: unknown): data is PeachifyInboundMessage {
  if (!data || typeof data !== 'object') return false;
  const type = (data as { type?: unknown }).type;
  return type === 'PLAYER_EVENT' || type === 'MEDIA_DATA';
}

/**
 * postMessage bridge for a Peachify iframe: playback control + progress sync.
 */
export class PeachifyController {
  private iframe: HTMLIFrameElement | null = null;
  private boundListener: ((event: MessageEvent) => void) | null = null;
  private destroyed = false;
  private lastTimeupdateAt = 0;

  readonly origin: string;
  readonly persistProgress: boolean;
  readonly storageKey: string;
  readonly timeupdateThrottleMs: number;
  readonly onMediaData?: (store: PeachifyProgressStore) => void;
  readonly onPlayerEvent?: (data: PeachifyPlayerEventData) => void;

  constructor(options: PeachifyControllerOptions = {}) {
    this.origin = options.origin ?? PEACHIFY_ORIGIN;
    this.persistProgress = options.persistProgress !== false;
    this.storageKey = options.storageKey ?? 'peachifyProgress';
    this.timeupdateThrottleMs = options.timeupdateThrottleMs ?? 1000;
    this.onMediaData = options.onMediaData;
    this.onPlayerEvent = options.onPlayerEvent;
  }

  /** Attach to an iframe and start listening for player messages. */
  attach(iframe: HTMLIFrameElement): void {
    this.detach();
    this.iframe = iframe;
    this.destroyed = false;

    this.boundListener = (event: MessageEvent) => this.handleMessage(event);
    window.addEventListener('message', this.boundListener);
  }

  detach(): void {
    if (this.boundListener) {
      window.removeEventListener('message', this.boundListener);
      this.boundListener = null;
    }
    this.iframe = null;
  }

  destroy(): void {
    this.destroyed = true;
    this.detach();
  }

  private handleMessage(event: MessageEvent): void {
    if (this.destroyed) return;
    if (event.origin !== this.origin) return;
    if (this.iframe && event.source !== this.iframe.contentWindow) return;
    if (!isPeachifyInboundMessage(event.data)) return;

    if (event.data.type === 'MEDIA_DATA') {
      const store = event.data.data;
      if (this.persistProgress && typeof localStorage !== 'undefined') {
        mergePeachifyProgress(store, this.storageKey);
      }
      this.onMediaData?.(store);
      return;
    }

    const payload = event.data.data;
    if (payload.event === 'timeupdate') {
      const now = Date.now();
      if (now - this.lastTimeupdateAt < this.timeupdateThrottleMs) {
        return;
      }
      this.lastTimeupdateAt = now;
    }

    this.onPlayerEvent?.(payload);
  }

  /** Send a command to the embedded player. */
  post(command: PeachifyCommand, value?: number): void {
    const win = this.iframe?.contentWindow;
    if (!win) {
      console.warn('[PeachifyController] No iframe attached');
      return;
    }
    const message: PeachifyOutboundMessage = { command };
    if (value !== undefined) {
      message.value = value;
    }
    win.postMessage(message, this.origin);
  }

  play(): void {
    this.post('play');
  }

  pause(): void {
    this.post('pause');
  }

  seek(seconds: number): void {
    this.post('seek', seconds);
  }

  setVolume(level: number): void {
    this.post('setVolume', Math.min(1, Math.max(0, level)));
  }

  toggleMute(): void {
    this.post('toggleMute');
  }

  toggleFullscreen(): void {
    this.post('toggleFullscreen');
  }

  getStatus(): void {
    this.post('getStatus');
  }
}

'use client';

import {
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useMemo,
  useRef,
  forwardRef,
} from 'react';
import {
  buildPeachifyEmbedUrl,
  getResumeSeconds,
  loadPeachifyProgress,
  PeachifyController,
  type PeachifyControllerOptions,
  type PeachifyEmbedTarget,
  type PeachifyPlayerEventData,
  type PeachifyProgressStore,
} from '../peachify';

export interface PeachifyPlayerHandle {
  controller: PeachifyController;
  play: () => void;
  pause: () => void;
  seek: (seconds: number) => void;
  setVolume: (level: number) => void;
  toggleMute: () => void;
  toggleFullscreen: () => void;
  getStatus: () => void;
}

export interface PeachifyPlayerProps {
  target: PeachifyEmbedTarget;
  /** Resume from localStorage progress when startAt is not set in options. Default: true */
  autoResume?: boolean;
  /** Merge controller options (callbacks, storage key, throttle). */
  controllerOptions?: Omit<PeachifyControllerOptions, 'onMediaData' | 'onPlayerEvent'>;
  onMediaData?: (store: PeachifyProgressStore) => void;
  onPlayerEvent?: (data: PeachifyPlayerEventData) => void;
  className?: string;
  title?: string;
  /** iframe allow attribute */
  allow?: string;
  /** Called when the iframe fires its load event */
  onIframeLoad?: () => void;
}

const DEFAULT_ALLOW =
  'autoplay; fullscreen; picture-in-picture; encrypted-media';

export const PeachifyPlayer = forwardRef<PeachifyPlayerHandle, PeachifyPlayerProps>(
  function PeachifyPlayer(
    {
      target,
      autoResume = true,
      controllerOptions,
      onMediaData,
      onPlayerEvent,
      className,
      title = 'Video player',
      allow = DEFAULT_ALLOW,
      onIframeLoad,
    },
    ref,
  ) {
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const controllerRef = useRef<PeachifyController | null>(null);
    const reactId = useId();
    const iframeId = `peachify-player-${reactId.replace(/:/g, '')}`;

    const embedUrl = useMemo(() => {
      const options = { ...target.options };

      if (
        autoResume &&
        options.startAt == null &&
        options.progress == null &&
        options.t == null &&
        typeof window !== 'undefined'
      ) {
        const store = loadPeachifyProgress(controllerOptions?.storageKey);
        const resume =
          target.type === 'tv'
            ? getResumeSeconds(
                store,
                target.mediaId,
                target.season,
                target.episode,
              )
            : getResumeSeconds(store, target.mediaId);

        if (resume != null) {
          options.startAt = resume;
        }
      }

      return buildPeachifyEmbedUrl({ ...target, options });
    }, [target, autoResume, controllerOptions?.storageKey]);

    const getController = useCallback(() => {
      if (!controllerRef.current) {
        controllerRef.current = new PeachifyController({
          ...controllerOptions,
          onMediaData,
          onPlayerEvent,
        });
      }
      return controllerRef.current;
    }, [controllerOptions, onMediaData, onPlayerEvent]);

    useImperativeHandle(
      ref,
      () => {
        const controller = getController();
        return {
          controller,
          play: () => controller.play(),
          pause: () => controller.pause(),
          seek: (s) => controller.seek(s),
          setVolume: (v) => controller.setVolume(v),
          toggleMute: () => controller.toggleMute(),
          toggleFullscreen: () => controller.toggleFullscreen(),
          getStatus: () => controller.getStatus(),
        };
      },
      [getController],
    );

    useEffect(() => {
      const iframe = iframeRef.current;
      if (!iframe) return;

      const controller = getController();
      controller.attach(iframe);

      return () => {
        controller.detach();
      };
    }, [embedUrl, getController]);

    useEffect(() => {
      return () => {
        controllerRef.current?.destroy();
        controllerRef.current = null;
      };
    }, []);

    return (
      <div className={className} data-peachify-player>
        <iframe
          ref={iframeRef}
          id={iframeId}
          src={embedUrl}
          title={title}
          allow={allow}
          allowFullScreen
          referrerPolicy="origin"
          style={{
            width: '100%',
            aspectRatio: '16 / 9',
            border: 0,
            display: 'block',
            background: '#000',
          }}
          onLoad={onIframeLoad}
        />
      </motion.div>
    );
  },
);

/**
 * Vanilla JS Peachify embed helper (no build step).
 * Copy into your site or load as a module: import from peachify/index.ts in bundled apps.
 */
(function (global) {
  const PEACHIFY_ORIGIN = 'https://peachify.top';
  const DEFAULT_STORAGE_KEY = 'peachifyProgress';

  const HIDE_KEYS = [
    'pip', 'cast', 'fullscreen', 'volume', 'servers', 'captions', 'quality',
    'play', 'rewind', 'forward', 'timegroup', 'timeslider', 'settings',
  ];

  function encodeMediaId(mediaId) {
    const raw = String(mediaId).trim();
    if (/^tt\d+$/i.test(raw)) return raw.toLowerCase();
    const n = Number(raw);
    if (!Number.isFinite(n) || n <= 0) {
      throw new Error('mediaId must be TMDB numeric or IMDb tt-prefixed id');
    }
    return String(Math.trunc(n));
  }

  function hideValue(v) {
    if (v === true) return 'hide';
    if (v === false) return 'false';
    return String(v);
  }

  function buildPeachifyEmbedUrl(target) {
    const id = encodeMediaId(target.mediaId);
    const o = target.options || {};
    const path =
      target.type === 'movie'
        ? `/embed/movie/${id}`
        : `/embed/tv/${id}/${Math.max(1, target.season | 0)}/${Math.max(1, target.episode | 0)}`;

    const url = new URL(path, PEACHIFY_ORIGIN);
    const p = url.searchParams;

    if (o.dub || o.audio) p.set('dub', o.dub || o.audio);
    if (o.sub || o.subtitle) p.set('sub', o.sub || o.subtitle);
    if (o.quality != null || o.q != null) p.set('quality', String(o.quality ?? o.q));
    if (o.server) p.set('server', o.server);
    if (o.api) p.set('api', o.api);

    const start = o.startAt ?? o.progress ?? o.t;
    if (start != null) p.set('startAt', String(start));

    if (target.type === 'tv') {
      if (o.autoNext != null) p.set('autoNext', String(o.autoNext));
      const next = o.showNextBtn ?? o.showAutoNextButton ?? o.nextEpisodeButton;
      if (next != null) p.set('showNextBtn', next ? 'true' : 'false');
    }

    if (o.accent) p.set('accent', String(o.accent).replace(/^#/, ''));
    if (o.autoPlay === false) p.set('autoPlay', 'false');

    for (const k of HIDE_KEYS) {
      if (o[k] !== undefined) p.set(k, hideValue(o[k]));
    }

    return url.toString();
  }

  function loadProgress(key) {
    key = key || DEFAULT_STORAGE_KEY;
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  }

  function mergeProgress(incoming, key) {
    key = key || DEFAULT_STORAGE_KEY;
    const merged = { ...loadProgress(key), ...incoming };
    localStorage.setItem(key, JSON.stringify(merged));
    return merged;
  }

  function getResumeSeconds(store, mediaId, season, episode, threshold) {
    threshold = threshold ?? 30;
    const entry = store && store[String(mediaId)];
    if (!entry) return undefined;

    let watched, duration;
    if (season != null && episode != null && entry.show_progress) {
      const ep = entry.show_progress[`s${season}e${episode}`];
      watched = ep && ep.progress && ep.progress.watched;
      duration = ep && ep.progress && ep.progress.duration;
    } else {
      watched = entry.progress && entry.progress.watched;
      duration = entry.progress && entry.progress.duration;
    }

    if (watched == null || watched <= 0) return undefined;
    if (duration != null && duration - watched <= threshold) return undefined;
    return Math.floor(watched);
  }

  function PeachifyController(options) {
    options = options || {};
    this.origin = options.origin || PEACHIFY_ORIGIN;
    this.storageKey = options.storageKey || DEFAULT_STORAGE_KEY;
    this.persistProgress = options.persistProgress !== false;
    this.timeupdateThrottleMs = options.timeupdateThrottleMs ?? 1000;
    this.onMediaData = options.onMediaData;
    this.onPlayerEvent = options.onPlayerEvent;
    this._iframe = null;
    this._lastTU = 0;
    this._onMessage = this._onMessage.bind(this);
  }

  PeachifyController.prototype.attach = function (iframe) {
    this.detach();
    this._iframe = iframe;
    window.addEventListener('message', this._onMessage);
  };

  PeachifyController.prototype.detach = function () {
    window.removeEventListener('message', this._onMessage);
    this._iframe = null;
  };

  PeachifyController.prototype.destroy = function () {
    this.detach();
  };

  PeachifyController.prototype._onMessage = function (event) {
    if (event.origin !== this.origin) return;
    if (this._iframe && event.source !== this._iframe.contentWindow) return;

    const data = event.data;
    if (!data || typeof data !== 'object') return;

    if (data.type === 'MEDIA_DATA') {
      if (this.persistProgress) mergeProgress(data.data, this.storageKey);
      if (this.onMediaData) this.onMediaData(data.data);
      return;
    }

    if (data.type === 'PLAYER_EVENT' && data.data) {
      if (data.data.event === 'timeupdate') {
        const now = Date.now();
        if (now - this._lastTU < this.timeupdateThrottleMs) return;
        this._lastTU = now;
      }
      if (this.onPlayerEvent) this.onPlayerEvent(data.data);
    }
  };

  PeachifyController.prototype.post = function (command, value) {
    if (!this._iframe || !this._iframe.contentWindow) return;
    const msg = { command: command };
    if (value !== undefined) msg.value = value;
    this._iframe.contentWindow.postMessage(msg, this.origin);
  };

  PeachifyController.prototype.play = function () { this.post('play'); };
  PeachifyController.prototype.pause = function () { this.post('pause'); };
  PeachifyController.prototype.seek = function (s) { this.post('seek', s); };
  PeachifyController.prototype.setVolume = function (v) {
    this.post('setVolume', Math.min(1, Math.max(0, v)));
  };
  PeachifyController.prototype.toggleMute = function () { this.post('toggleMute'); };
  PeachifyController.prototype.toggleFullscreen = function () { this.post('toggleFullscreen'); };
  PeachifyController.prototype.getStatus = function () { this.post('getStatus'); };

  /**
   * Mount player into a container element.
   * @returns {{ iframe: HTMLIFrameElement, controller: PeachifyController, url: string }}
   */
  function mountPeachifyPlayer(container, target, options) {
    options = options || {};
    const autoResume = options.autoResume !== false;
    const embedOptions = Object.assign({}, target.options || {});

    if (
      autoResume &&
      embedOptions.startAt == null &&
      embedOptions.progress == null &&
      embedOptions.t == null
    ) {
      const store = loadProgress(options.storageKey);
      const resume =
        target.type === 'tv'
          ? getResumeSeconds(store, target.mediaId, target.season, target.episode)
          : getResumeSeconds(store, target.mediaId);
      if (resume != null) embedOptions.startAt = resume;
    }

    const url = buildPeachifyEmbedUrl(Object.assign({}, target, { options: embedOptions }));

    const iframe = document.createElement('iframe');
    iframe.src = url;
    iframe.title = options.title || 'Video player';
    iframe.allow = options.allow || 'autoplay; fullscreen; picture-in-picture; encrypted-media';
    iframe.allowFullscreen = true;
    iframe.referrerPolicy = 'origin';
    iframe.style.cssText =
      'width:100%;aspect-ratio:16/9;border:0;display:block;background:#000';

    container.innerHTML = '';
    container.appendChild(iframe);

    const controller = new PeachifyController(options.controllerOptions);
    controller.attach(iframe);

    return { iframe: iframe, controller: controller, url: url };
  }

  const api = {
    PEACHIFY_ORIGIN: PEACHIFY_ORIGIN,
    buildPeachifyEmbedUrl: buildPeachifyEmbedUrl,
    loadPeachifyProgress: loadProgress,
    mergePeachifyProgress: mergeProgress,
    getResumeSeconds: getResumeSeconds,
    PeachifyController: PeachifyController,
    mountPeachifyPlayer: mountPeachifyPlayer,
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
  global.Peachify = api;
})(typeof window !== 'undefined' ? window : globalThis);

