export const allMedia: MediaItem[] = [...movies, ...tvShows];

export const featured: MediaItem = movies[0];

export function getMovie(id: number): Movie | undefined {
  return movies.find((m) => m.id === id);
}

export function getTvShow(id: number): TvShow | undefined {
  return tvShows.find((t) => t.id === id);
}

export function getMedia(id: number): MediaItem | undefined {
  return allMedia.find((m) => m.id === id);
}

export function searchCatalog(query: string): MediaItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return allMedia.filter(
    (m) =>
      m.title.toLowerCase().includes(q) ||
      m.overview.toLowerCase().includes(q) ||
      m.genres.some((g) => g.toLowerCase().includes(q)),
  );
}

export function watchMovieHref(id: number): string {
  return `/watch/movie/${id}`;
}

export function watchTvHref(id: number, season: number, episode: number): string {
  return `/watch/tv/${id}/${season}/${episode}`;
}

export function movieDetailHref(id: number): string {
  return `/movie/${id}`;
}

export function tvDetailHref(id: number): string {
  return `/tv/${id}`;
}

'use client';

import {
  getCompletionRatio,
  getMediaProgress,
  loadPeachifyProgress,
} from '@/peachify';
import type { PeachifyProgressStore } from '@/peachify';
import {
  allMedia,
  getMedia,
  watchMovieHref,
  watchTvHref,
} from '@/lib/catalog';
import type { ContinueWatchingItem } from '@/types/media';

export function buildContinueWatching(
  store?: PeachifyProgressStore,
): ContinueWatchingItem[] {
  const progress = store ?? loadPeachifyProgress();
  const items: ContinueWatchingItem[] = [];

  for (const key of Object.keys(progress)) {
    const entry = progress[key];
    if (!entry?.progress) continue;

    const catalog = getMedia(entry.id);
    if (!catalog) continue;

    const ratio = getCompletionRatio(entry);
    if (ratio <= 0.02 || ratio >= 0.98) continue;

    if (entry.type === 'movie' && catalog.type === 'movie') {
      items.push({
        id: entry.id,
        type: 'movie',
        title: entry.title || catalog.title,
        poster_path: entry.poster_path || catalog.poster_path,
        progressPercent: Math.round(ratio * 100),
        href: watchMovieHref(entry.id),
      });
      continue;
    }

    if (entry.type === 'tv' && catalog.type === 'tv') {
      const season = Number(entry.last_season_watched ?? 1);
      const episode = Number(entry.last_episode_watched ?? 1);
      const epKey = `s${season}e${episode}`;
      const epProgress = entry.show_progress?.[epKey]?.progress ?? entry.progress;
      const epRatio =
        epProgress.duration > 0
          ? Math.min(1, epProgress.watched / epProgress.duration)
          : ratio;

      if (epRatio <= 0.02 || epRatio >= 0.98) continue;

      items.push({
        id: entry.id,
        type: 'tv',
        title: entry.title || catalog.title,
        poster_path: entry.poster_path || catalog.poster_path,
        progressPercent: Math.round(epRatio * 100),
        href: watchTvHref(entry.id, season, episode),
        subtitle: `S${season} · E${episode}`,
      });
    }
  }

  return items.sort((a, b) => b.progressPercent - a.progressPercent).slice(0, 12);
}

export function enrichFromCatalog(store: PeachifyProgressStore): PeachifyProgressStore {
  const enriched = { ...store };
  for (const key of Object.keys(enriched)) {
    const entry = enriched[key];
    const catalog = allMedia.find((m) => m.id === entry.id);
    if (!catalog) continue;
    enriched[key] = {
      ...entry,
      title: entry.title || catalog.title,
      poster_path: entry.poster_path || catalog.poster_path,
    };
  }
  return enriched;
}

export { getMediaProgress, loadPeachifyProgress };

'use client';

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';
import {
  buildPeachifyEmbedUrl,
  getResumeSeconds,
  loadPeachifyProgress,
  PeachifyController,
  type PeachifyControllerOptions,
  type PeachifyEmbedTarget,
  type PeachifyPlayerEventData,
  type PeachifyProgressStore,
} from '@/peachify';

export interface PeachifyPlayerHandle {
  controller: PeachifyController;
  play: () => void;
  pause: () => void;
  seek: (seconds: number) => void;
  setVolume: (level: number) => void;
  toggleMute: () => void;
  toggleFullscreen: () => void;
  getStatus: () => void;
}

export interface PeachifyPlayerProps {
  target: PeachifyEmbedTarget;
  autoResume?: boolean;
  controllerOptions?: Omit<
    PeachifyControllerOptions,
    'onMediaData' | 'onPlayerEvent'
  >;
  onMediaData?: (store: PeachifyProgressStore) => void;
  onPlayerEvent?: (data: PeachifyPlayerEventData) => void;
  className?: string;
  title?: string;
  allow?: string;
  onIframeLoad?: () => void;
}

const DEFAULT_ALLOW =
  'autoplay; fullscreen; picture-in-picture; encrypted-media';

export const PeachifyPlayer = forwardRef<
  PeachifyPlayerHandle,
  PeachifyPlayerProps
>(function PeachifyPlayer(
  {
    target,
    autoResume = true,
    controllerOptions,
    onMediaData,
    onPlayerEvent,
    className,
    title = 'Video player',
    allow = DEFAULT_ALLOW,
    onIframeLoad,
  },
  ref,
) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const controllerRef = useRef<PeachifyController | null>(null);
  const reactId = useId();
  const iframeId = `peachify-player-${reactId.replace(/:/g, '')}`;

  const embedUrl = useMemo(() => {
    const options = { ...target.options };

    if (
      autoResume &&
      options.startAt == null &&
      options.progress == null &&
      options.t == null &&
      typeof window !== 'undefined'
    ) {
      const store = loadPeachifyProgress(controllerOptions?.storageKey);
      const resume =
        target.type === 'tv'
          ? getResumeSeconds(
              store,
              target.mediaId,
              target.season,
              target.episode,
            )
          : getResumeSeconds(store, target.mediaId);

      if (resume != null) {
        options.startAt = resume;
      }
    }

    return buildPeachifyEmbedUrl({ ...target, options });
  }, [target, autoResume, controllerOptions?.storageKey]);

  const getController = useCallback(() => {
    if (!controllerRef.current) {
      controllerRef.current = new PeachifyController({
        ...controllerOptions,
        onMediaData,
        onPlayerEvent,
      });
    }
    return controllerRef.current;
  }, [controllerOptions, onMediaData, onPlayerEvent]);

  useImperativeHandle(
    ref,
    () => {
      const controller = getController();
      return {
        controller,
        play: () => controller.play(),
        pause: () => controller.pause(),
        seek: (s) => controller.seek(s),
        setVolume: (v) => controller.setVolume(v),
        toggleMute: () => controller.toggleMute(),
        toggleFullscreen: () => controller.toggleFullscreen(),
        getStatus: () => controller.getStatus(),
      };
    },
    [getController],
  );

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    const controller = getController();
    controller.attach(iframe);

    return () => {
      controller.detach();
    };
  }, [embedUrl, getController]);

  useEffect(() => {
    return () => {
      controllerRef.current?.destroy();
      controllerRef.current = null;
    };
  }, []);

  return (
    <motion.div className={className} data-peachify-player>
      <iframe
        ref={iframeRef}
        id={iframeId}
        src={embedUrl}
        title={title}
        allow={allow}
        allowFullScreen
        referrerPolicy="origin"
        className="aspect-video w-full border-0 bg-black"
        onLoad={onIframeLoad}
      />
    </motion.div>
  );
});

