export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string; season: string; episode: string }>;
}): Promise<Metadata> {
  const { id, season, episode } = await params;
  const show = getTvShow(Number(id));
  if (!show) return { title: 'Watch' };
  return {
    title: `Watch ${show.title} S${season}E${episode}`,
  };
}

function findEpisode(
  show: NonNullable<ReturnType<typeof getTvShow>>,
  seasonNum: number,
  episodeNum: number,
) {
  const season = show.seasons.find((s) => s.season_number === seasonNum);
  return season?.episodes.find((e) => e.episode === episodeNum);
}

function findNextEpisode(
  show: NonNullable<ReturnType<typeof getTvShow>>,
  seasonNum: number,
  episodeNum: number,
) {
  const season = show.seasons.find((s) => s.season_number === seasonNum);
  if (!season) return null;

  const idx = season.episodes.findIndex((e) => e.episode === episodeNum);
  if (idx >= 0 && idx < season.episodes.length - 1) {
    const next = season.episodes[idx + 1];
    return { season: seasonNum, episode: next.episode, title: next.title };
  }

  const seasonIdx = show.seasons.findIndex((s) => s.season_number === seasonNum);
  const nextSeason = show.seasons[seasonIdx + 1];
  if (nextSeason?.episodes[0]) {
    const ep = nextSeason.episodes[0];
    return {
      season: nextSeason.season_number,
      episode: ep.episode,
      title: ep.title,
    };
  }

  return null;
}

export default async function WatchTvPage({
  params,
}: {
  params: Promise<{ id: string; season: string; episode: string }>;
}) {
  const { id, season: s, episode: e } = await params;
  const showId = Number(id);
  const season = Number(s);
  const episode = Number(e);

  const show = getTvShow(showId);
  if (!show || !Number.isFinite(season) || !Number.isFinite(episode)) {
    notFound();
  }

  const current = findEpisode(show, season, episode);
  if (!current) notFound();

  const next = findNextEpisode(show, season, episode);
  const title = `${show.title} · S${season}E${episode} — ${current.title}`;

  return (
    <WatchLayout
      title={title}
      backHref={tvDetailHref(show.id)}
      target={{
        type: 'tv',
        mediaId: show.id,
        season,
        episode,
      }}
      nextHref={
        next ? watchTvHref(show.id, next.season, next.episode) : undefined
      }
      nextLabel={next ? `Next: ${next.title}` : undefined}
    />
  );
}

