  useState,
  type ReactNode,
} from 'react';

interface ScrollRowProps {
  title: string;
  children: ReactNode;
  className?: string;
}

function ChevronLeft() {
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden>
      <path
        d="M15 6l-6 6 6 6"
        stroke="currentColor"
